(self.webpackChunkkernel_community=self.webpackChunkkernel_community||[]).push([[1002],{17414:function(e,t,a){"use strict";a.r(t),a.d(t,{_frontmatter:function(){return s},default:function(){return v}});var n=a(19756),o=(a(67294),a(63497)),i=a(60975),r=["components"],s={},l=function(e){return function(t){return console.warn("Component "+e+" was not imported, exported, or provided by MDXProvider as global scope"),(0,o.kt)("div",t)}},h=l("InfoBlock"),c=l("Video"),u=l("Column"),p=l("Box"),m=l("Aligner"),f=l("Image"),d=l("Button"),w=l("List"),k=l("Link"),y={_frontmatter:s},g=i.Z;function v(e){var t=e.components,a=(0,n.Z)(e,r);return(0,o.kt)(g,Object.assign({},y,a,{components:t,mdxType:"MDXLayout"}),(0,o.kt)("h1",{id:"️-transform-the-internet",style:{position:"relative"}},"🖌️ Transform the internet",(0,o.kt)("a",{parentName:"h1",href:"#%EF%B8%8F-transform-the-internet","aria-label":"️ transform the internet permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Two short video essays start off our curated materials for the week. We invite you to consider how we can artfully relate the internet to our current institutions and thereby transform both."),(0,o.kt)(h,{mdxType:"InfoBlock"},(0,o.kt)(c,{src:"https://www.youtube-nocookie.com/embed/783hwpJTjlo",mdxType:"Video"}),(0,o.kt)(c,{src:"https://www.youtube-nocookie.com/embed/uXUK9WpwmIs",mdxType:"Video"})),(0,o.kt)("h3",{id:"how-does-this-fit-into-kernel",style:{position:"relative"}},"How does this fit into Kernel?",(0,o.kt)("a",{parentName:"h3",href:"#how-does-this-fit-into-kernel","aria-label":"how does this fit into kernel permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Art is that which gets us to question value and meaning most deeply. These videos, themselves a series of artful expressions cut together with digital tools, reveal some aspects of the enormity of what we can craft with careful intention, attention, and a deep appreciation for the meaning of our media environments."),(0,o.kt)("p",null,"The question this brief is crafted around/within is simple: what is the proper subject of art? Is it in any way related to the subject(s) of internet-age institutions?"),(0,o.kt)("h2",{id:"brief",style:{position:"relative"}},"Brief",(0,o.kt)("a",{parentName:"h2",href:"#brief","aria-label":"brief permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Art begins with work which throws a veil over the invisible so its outline may be seen. It is brought to completion in the moment of encounter with an other. That is, art is not created as you are painting, or writing, or composing, or sculpting, or coding. It ",(0,o.kt)("em",{parentName:"p"},"occurs")," when your work inspires an experience of a state of consciousness otherwise unknown."),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},"💡 At its best, art transmits what cannot be said, or sung, or heard, or felt.")),(0,o.kt)("p",null,"We have always used technology to achieve this. For instance, the invention of metal ",(0,o.kt)("a",{parentName:"p",href:"https://primetimepaint.ca/a-brief-history-of-the-paintbrush/"},"ferrules"),"—the little bit that connects the bristles to the shaft—led to the flat paint brushes so beloved by Impressionist painters, who used them to capture the effects of light in different environments. Technological innovations in the tools we use to express ourselves often result in significant artistic advances in sight, perception, philosophy and—ultimately—culture."),(0,o.kt)("p",null,'Our proposition in putting all this to you is that there is, in fact, a "proper" subject of art. Which is not a very popular proposition in modern culture, after all the many movements and -isms of the last few centuries. Moreover, this proper subject is the sacred. By "sacred", we do not mean religious, nor do we wish to confine art in any way to any particular kind of content or mode of expression. The sacred, as we will explore in Module 7, is simply that which is greater than me. That which connects, that which continues, that which relates all of these differences in space and time—with due respect and reverence for such diversity—to our single origin and destiny. '),(0,o.kt)("p",null,'In art, the sacred is something like an atmosphere, connected to the ancient Hebrew concept of "shem", which is often translated as "name". This is not just the specific sound by which you are called, but the whole sound and light and vibration of your being; that which radiates from your heart and infuses those who encounter you and your work with the unique message you are scent with.'),(0,o.kt)("p",null,"The idea that art is the province of that which is greater than just me and my struggles is prevalent across cultures, and still observed closely in many non-Western traditions. For instance, ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=oqsA_v4Nu4U&t=1149s"},'here is Oliver Mtukudzi talking about the "purpose of song" in Shona culture'),". It is, according to Mtukudzi:"),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},'"To give life and hope to the people. To heal the broken hearts."')),(0,o.kt)("h2",{id:"ceremony",style:{position:"relative"}},"Ceremony",(0,o.kt)("a",{parentName:"h2",href:"#ceremony","aria-label":"ceremony permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Following this line of inquiry, we can investigate what it would mean to make online, transactional spaces more artistic. Which is to say, now that money is programmable, are there ways we might merge individual expressions of what is held to be sacred with what we all agree to have meaningful economic value? This is not to say that doing so is better or worse than any other artistic possibility, it is simply to point out that such action is now available to us by virtue of the state of our shared technologies."),(0,o.kt)("p",null,"One example of this is ",(0,o.kt)("a",{parentName:"p",href:"https://restore.pr1s0n.art/#/nfts/0"},"Prison Art"),". Another may be ",(0,o.kt)("a",{parentName:"p",href:"https://finding.thebluebook.co.za"},"found here"),"."),(0,o.kt)("p",null,"The point this brings us to is a surprising one, because it turns out that there is a prerequisite for this form of art to really flourish. It is a prerequisite which links art and its proper subject to the subjects of internet-age institutions. The prerequisite is privacy."),(0,o.kt)("h2",{id:"the-private-public",style:{position:"relative"}},"The Private Public",(0,o.kt)("a",{parentName:"h2",href:"#the-private-public","aria-label":"the private public permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Technological privacy is often discussed in contexts which makes it difficult to distinguish from the covert, the hidden, that which is by nature suspicious. Its advocates are often eloquent in their attempts to illustrate why this is not true, why ",(0,o.kt)("a",{parentName:"p",href:"https://en.wikipedia.org/wiki/Right_to_privacy"},"privacy is a human right"),", why ",(0,o.kt)("a",{parentName:"p",href:"https://x.com/VitalikButerin/status/1779845886224253369"},"privacy is normal")," and why ",(0,o.kt)("a",{parentName:"p",href:"https://www.npr.org/2020/03/20/818341273/edward-snowden-why-does-online-privacy-matter"},"you should care about it")," rather than cringe slightly at the thought of needing to hide stuff and then remember where it is and how to access it."),(0,o.kt)("p",null,"You can find good examples of such work ",(0,o.kt)("a",{parentName:"p",href:"https://craphound.com/tag/privacy/"},"here")," and ",(0,o.kt)("a",{parentName:"p",href:"https://moxie.org/2013/06/12/we-should-all-have-something-to-hide.html"},"here"),". You can see ",(0,o.kt)("a",{parentName:"p",href:"https://vitalik.eth.limo/general/2023/12/28/cypherpunk.html#ethereum-as-part-of-a-broader-technological-vision"},"how all this fits into Ethereum here"),". You can join many other Kernel fellows doing privacy related work ",(0,o.kt)("a",{parentName:"p",href:"https://web3privacy.info/"},"here"),"."),(0,o.kt)("p",null,'When approached through the lens of art and the so-called "humanities", though, the context is quite different. We do not need to justify what is kept private, it flows naturally from experiencing the practice of art. That is, as Kernel fellow Joan writes, '),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},'"The meaning of me sharing something with you voluntarily is very different from the meaning of any information you may be able to forcefully gain from me, or about me. Take away privacy, and you take away my free choice - then I can no longer share voluntarily, and ',(0,o.kt)("strong",{parentName:"p"},"you will never know what it is to be trusted"),'."')),(0,o.kt)("p",null,'Fully public environments do not allow for this kind of nuanced development of trust. In this sense, they may actually be "trustless", but that is perhaps not all it is cracked up to be. However, fully private environments also cannot, by definition, enable the sort of encounter and chosen vulnerability we\'ve been considering above. As Joan writes,'),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},'"a balance must be found between on the one extreme exposing everything to everyone always—which would not be tolerable, and most likely also would lead to the death of our fledgling initiatives—and on the other extreme keeping everything to ourselves always, isolating ourselves and denying our fledglings the chance to grow through contact with the world."')),(0,o.kt)("p",null,"Read through the lens of how we artfully develop trust,a document many refer to when discussing privacy–",(0,o.kt)("a",{parentName:"p",href:"https://www.activism.net/cypherpunk/manifesto.html"},"A Cypherpunk's Manifesto"),"–reveals something fascinating. It defines privacy as:"),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},(0,o.kt)("strong",{parentName:"p"},'"the power to selectively reveal oneself to the world"'))),(0,o.kt)("p",null,"Privacy is inseparable from acts of selective revelation. In this sense, it is indistinguishable from art. In either case, what is shared is deeply revealing information which could potentially be used to compromise its originator, and thus represents a real trust and gift, a true call to encounter the universal through my particular re-presentation, an invitation into the infinite."),(0,o.kt)("p",null,"The way in which such revelations occur is what links the proper subject of art above with the subject(s) of internet age institutions. When creating art or interacting with internet-age institutions at their best, we will be—in either case—throwing a veil over that which is most invisible to us: ourselves. This can be done in a crude fashion, like a poem about personal trauma that never takes you anywhere other than pain, or revealing information transmitted in plain text to a single server; or it can be done elegantly, like ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=6VrZE8MCnIA"},"this poem also about personal experience")," that resonates with much more, or something like ",(0,o.kt)("a",{parentName:"p",href:"https://github.com/proofcarryingdata/zupass"},"Zupass"),"."),(0,o.kt)("p",null,'Do we selectively reveal ourselves in such a way that concentrates wealth and power in so-called "',(0,o.kt)("a",{parentName:"p",href:"https://en.wikipedia.org/wiki/Who_Owns_the_Future%3F"},"siren servers"),'", or will we co-create protocols that do not require knowledge about their customers, only a succinct proof of what is most relevant in context? Do we selectively reveal ourselves in media that others own and extract value from, or will we co-create ceremonial transactions capable of carrying our unique encoding of sacred economics via the ',(0,o.kt)("a",{parentName:"p",href:"https://sign.kernel.community"},"shared signatures of all who participate"),"?"),(0,o.kt)("h2",{id:"no-knowledge-is-sufficient",style:{position:"relative"}},"No Knowledge is Sufficient",(0,o.kt)("a",{parentName:"h2",href:"#no-knowledge-is-sufficient","aria-label":"no knowledge is sufficient permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,'Artful revelations of trusted information that are contextual and succinct, and which do not concentrate wealth and power in a few hands may be achieved via "',(0,o.kt)("a",{parentName:"p",href:"https://learn.0xparc.org/"},"zero knowledge proofs"),'". In truth, art which revolves around the sacred also emanates from a state of zero knowledge, or what John Vervaeke calls "',(0,o.kt)("a",{parentName:"p",href:"https://youtu.be/erxLwlk6RCQ?t=505"},"learned ignorance"),'". '),(0,o.kt)("p",null,"Part of throwing a veil over the invisible—either in the context of creating art, or when interacting with internet-age institutions—is precisely the ability to ",(0,o.kt)("a",{parentName:"p",href:"https://libraryofbabel.info/bookmark.cgi?findinghomecoming"},"ignore all that is not relevant"),". This is not ignorance as crude dissociation or bypass: it is a finely honed skill premised on a wide grasp of all that could possibly relate to a given context and the wisdom to discern what truly matters right now. "),(0,o.kt)("p",null,"These kinds of artful and selective revelations are not currently how we interact with institutions online, precisely because we have just ported old authentication regimes into the digital realm. The practical effect of all KYC implementations we have ever seen is to make it more difficult for honest actors to comply without meaningfully making a difference to those who would be dishonest in either case. "),(0,o.kt)("p",null,"Indeed, the acronym is a total misnomer. No-one is looking to know their customers, whatever such knowledge might entail. We're looking for sufficient proof of particular details relevant to a specific context. ",(0,o.kt)("a",{parentName:"p",href:"https://vitalik.eth.limo/general/2022/06/15/using_snarks.html"},"Sufficient proof is a more powerful way to think")," about authentication and accountability more generally, because it more precisely orients us towards cryptography generally, zero knowledge proofs specifically, and the question of how we can provide sufficient assurance without exposing unnecessary data."),(0,o.kt)("p",null,"The world of sufficient assurance is very different from that of knowledge and identity, and is much more simple to reason about and create meaningful, beneficial technology for."),(0,o.kt)("p",null,"Once you know what is sufficient, we can ",(0,o.kt)("a",{parentName:"p",href:"https://libraryofbabel.info/bookmark.cgi?findingnoproof"},"open the conversation into that which is beyond proof"),"."),(0,o.kt)("h2",{id:"truly-world-wide",style:{position:"relative"}},"Truly World Wide",(0,o.kt)("a",{parentName:"h2",href:"#truly-world-wide","aria-label":"truly world wide permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)(u,{sx:{gap:"10%"},mdxType:"Column"},(0,o.kt)(p,{mdxType:"Box"},(0,o.kt)("p",null,(0,o.kt)("strong",{parentName:"p"},"Mother Earth Mother Board")),(0,o.kt)(m,{center:!0,mdxType:"Aligner"},(0,o.kt)(f,{alt:"Mother Earth Mother Board",src:"/images/mod4-img/mother-earth-board.jpg",mdxType:"Image"})),(0,o.kt)("p",null,"If you want to explore the physical reality we're throwing a veil over, this is as good a place to\nstart as any."),(0,o.kt)(m,{center:!0,mdxType:"Aligner"},(0,o.kt)(d,{to:"https://www.wired.com/1996/12/ffglass/",mdxType:"Button"},"Read"))),(0,o.kt)(p,{mdxType:"Box"},(0,o.kt)("p",null,(0,o.kt)("strong",{parentName:"p"},"Artificiality")),(0,o.kt)(m,{center:!0,mdxType:"Aligner"},(0,o.kt)(f,{alt:"Artificiality",src:"/images/mod4-img/artificial.webp",mdxType:"Image"})),(0,o.kt)("p",null,'Put the art back in artificiality with Werner Herzog. Search for "The Inner Chronicle of What We Are" if you enjoy this.'),(0,o.kt)(m,{center:!0,mdxType:"Aligner"},(0,o.kt)(d,{to:"https://www.youtube.com/watch?v=ogFN6ncIaD8",mdxType:"Button"},"Watch")))),(0,o.kt)(w,{mdxType:"List"},(0,o.kt)(k,{to:"https://www.youtube.com/watch?v=7gUh8j5ui0o",mdxType:"Link"},(0,o.kt)("p",null,"The Art of life")),(0,o.kt)(k,{to:"https://aeon.co/essays/art-like-loss-can-shock-us-into-our-authentic-self",mdxType:"Link"},(0,o.kt)("p",null,"The quality of their expressive intention"))))}v.isMDXComponent=!0}}]);
